import {
  open,
  mkdir,
  readFile,
  rename,
  writeFile,
  truncate,
} from 'node:fs/promises';
import {
  existsSync,
} from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

const LOG_NAME = 'bus.jsonl';
const TMP_NAME = 'bus.jsonl.tmp';

/**
 * JSON.stringify throws on circular references and BigInt; reject those along
 * with undefined / functions / non-finite numbers, which stringify silently
 * drops or turns into null.
 */
function serializeRecord(record) {
  const seen = new Set();
  const replacer = function (key, value) {
    if (typeof value === 'bigint') {
      throw new TypeError('record contains a BigInt');
    }
    if (typeof value === 'function') {
      throw new TypeError('record contains a function');
    }
    if (typeof value === 'undefined') {
      throw new TypeError('record contains undefined');
    }
    if (typeof value === 'number' && !Number.isFinite(value)) {
      throw new TypeError('record contains a non-finite number');
    }
    if (value !== null && typeof value === 'object') {
      if (seen.has(value)) {
        throw new TypeError('record contains a circular reference');
      }
      seen.add(value);
      // The same object legitimately appears more than once only when it is
      // genuinely shared (diamond, not cycle); track per-depth so we do not
      // flag it. Circularity is caught instead by a parent stack.
    }
    return value;
  };

  // Detecting cycles needs an ancestry stack rather than a visited set
  // (shared-but-acyclic references must be allowed).
  const stack = new Set();
  const check = (value) => {
    if (typeof value === 'bigint') {
      throw new TypeError('record contains a BigInt');
    }
    if (typeof value === 'function') {
      throw new TypeError('record contains a function');
    }
    if (typeof value === 'undefined') {
      throw new TypeError('record contains undefined');
    }
    if (typeof value === 'number' && !Number.isFinite(value)) {
      throw new TypeError('record contains a non-finite number');
    }
    if (value !== null && typeof value === 'object') {
      if (stack.has(value)) {
        throw new TypeError('record contains a circular reference');
      }
      stack.add(value);
      if (Array.isArray(value)) {
        for (const item of value) check(item);
      } else {
        for (const key of Object.keys(value)) check(value[key]);
      }
      stack.delete(value);
    }
  };
  check(record);

  return JSON.stringify(record, replacer);
}

async function createBus({ path: dir, fsync = false } = {}) {
  if (typeof dir !== 'string' || dir.length === 0) {
    throw new TypeError('createBus: "path" must be a non-empty string');
  }

  await mkdir(dir, { recursive: true });
  const logPath = path.join(dir, LOG_NAME);
  const tmpPath = path.join(dir, TMP_NAME);

  let seq = 0;
  let bytes = 0;
  let published = 0;
  let replayed = 0;
  const dedup = new Map(); // dedupKey -> { id, seq }

  // ---- recovery: replay any existing log, fixing a torn tail --------------
  let fileHandle = null;
  let validSize = 0;
  let sawAnyLine = false;

  if (existsSync(logPath)) {
    const raw = await readFile(logPath);
    validSize = raw.length;
    let pos = 0;
    const parseLines = (buf) => {
      let start = 0;
      for (let i = 0; i < buf.length; i++) {
        if (buf[i] === 0x0a) {
          const line = buf.toString('utf8', start, i);
          start = i + 1;
          if (line.length === 0) {
            sawAnyLine = true;
            continue;
          }
          applyLine(line);
          sawAnyLine = true;
        }
      }
      return start;
    };

    const applyLine = (line) => {
      let entry;
      try {
        entry = JSON.parse(line);
      } catch {
        throw new Error('corrupt log line');
      }
      if (entry && entry.t === 'm') {
        seq = entry.seq;
        bytes += entry.bytes;
        published += 1;
        if (typeof entry.d === 'string') {
          dedup.set(entry.d, { id: entry.id, seq: entry.seq });
        }
      } else if (entry && entry.t === 's') {
        replayed += entry.n;
      }
    };

    try {
      const consumed = parseLines(raw);
      validSize = consumed;
      // Anything after the last '\n' is a torn (partial) trailing line.
      if (consumed < raw.length) {
        const tail = raw.toString('utf8', consumed);
        if (tail.length > 0) {
          // A complete line missing only its newline: the write may have been
          // fully durable while the newline was not. Validate it; keep if it
          // parses, otherwise truncate.
          try {
            let entry = JSON.parse(tail);
            if (entry && (entry.t === 'm' || entry.t === 's')) {
              applyLine(tail);
              validSize = raw.length;
            } else {
              await truncate(logPath, consumed);
            }
          } catch {
            await truncate(logPath, consumed);
          }
        }
      }
      fileHandle = await open(logPath, 'a');
    } catch (err) {
      // Corruption strictly inside a completed line is unrecoverable.
      throw err;
    }
  } else {
    fileHandle = await open(logPath, 'a');
  }

  let chain = Promise.resolve();
  let closed = false;

  const append = async (line) => {
    const buf = Buffer.from(line, 'utf8');
    await fileHandle.write(buf, undefined, undefined);
    // fileHandle.write with an append-mode fd appends atomically per call.
    if (fsync) {
      await fileHandle.sync();
    }
  };

  const bus = {
    async publish(record) {
      if (closed) {
        throw new Error('bus is closed');
      }
      if (record === null || typeof record !== 'object' || Array.isArray(record)) {
        throw new TypeError('publish: record must be a JSON object');
      }

      const dedupKey = record.dedupKey;
      if (dedupKey !== undefined && typeof dedupKey !== 'string') {
        throw new TypeError('publish: dedupKey must be a string');
      }

      let serialized;
      try {
        serialized = serializeRecord(record);
      } catch (err) {
        throw err;
      }
      const size = Buffer.byteLength(serialized, 'utf8');

      // Reserve ordering / dedup result at call time so concurrent publishes
      // take sequence numbers in invocation order, and an in-flight first
      // publish already services duplicate resends.
      const existing = dedupKey !== undefined ? dedup.get(dedupKey) : undefined;
      let result;
      if (existing) {
        result = Promise.resolve({ id: existing.id, seq: existing.seq });
      } else {
        const mySeq = ++seq;
        const id = randomUUID();
        if (dedupKey !== undefined) {
          dedup.set(dedupKey, { id, seq: mySeq });
        }
        result = chain.then(async () => {
          if (closed) {
            throw new Error('bus is closed');
          }
          const entry = {
            t: 'm',
            seq: mySeq,
            id,
            bytes: size,
            record,
          };
          if (dedupKey !== undefined) entry.d = dedupKey;
          await append(JSON.stringify(entry) + '\n');
          bytes += size;
          published += 1;
          return { id, seq: mySeq };
        });
        // Keep the chain moving even if this publish rejects, and never let a
        // failed write leave a reserved seq hole visible: the reservation is
        // part of the append that just failed, so roll it back.
        chain = result.then(
          () => {},
          () => {
            if (!closed) {
              seq = mySeq - 1;
              if (dedupKey !== undefined && dedup.get(dedupKey)?.id === id) {
                dedup.delete(dedupKey);
              }
            }
          },
        );
      }
      return result;
    },

    async replay(from = 0) {
      if (closed) {
        throw new Error('bus is closed');
      }
      if (
        typeof from !== 'number' ||
        !Number.isInteger(from) ||
        from < 0
      ) {
        throw new RangeError('replay: from must be a non-negative integer');
      }

      return chain.then(async () => {
        const raw = await readFile(logPath);
        const out = [];
        let start = 0;
        for (let i = 0; i < raw.length; i++) {
          if (raw[i] === 0x0a) {
            const line = raw.toString('utf8', start, i);
            start = i + 1;
            if (line.length === 0) continue;
            const entry = JSON.parse(line);
            if (entry.t === 'm' && entry.seq >= from) {
              out.push({ seq: entry.seq, id: entry.id, record: entry.record });
            }
          }
        }
        const n = out.length;
        if (n > 0) {
          await append(JSON.stringify({ t: 's', n }) + '\n');
          replayed += n;
        }
        return out;
      });
    },

    stats() {
      return { seq, bytes, published, replayed };
    },

    async close() {
      if (closed) return;
      closed = true;
      const done = chain.then(async () => {
        if (fsync) {
          try {
            await fileHandle.sync();
          } catch {
            // closing; ignore
          }
        }
        await fileHandle.close();
      });
      chain = done.catch(() => {});
      await done;
    },
  };

  return bus;
}

export { createBus };
export default { createBus };

